const body = $json.body ?? $json;
const title = String(body.title ?? '').trim();
if (!title) {
  throw new Error('title is required');
}
const slugBase = title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 80);
return [{
  json: {
    title,
    slug: `${slugBase}-${Date.now()}`,
    category: body.category ?? 'general',
    confidence_label: body.confidence_label ?? 'unverified',
    target_duration_seconds: Number(body.target_duration_seconds ?? 45),
    source_payload_json: body.source_payload_json ?? {},
    status: 'idea_approved'
  }
}];

return [{
  json: {
    ...$json,
    title_sql: String($json.title ?? '').replaceAll("'", "''"),
    slug_sql: String($json.slug ?? '').replaceAll("'", "''"),
    category_sql: String($json.category ?? 'general').replaceAll("'", "''"),
    confidence_label_sql: String($json.confidence_label ?? 'unverified').replaceAll("'", "''"),
    target_duration_seconds_sql: Number($json.target_duration_seconds ?? 45),
    source_payload_json_sql: JSON.stringify($json.source_payload_json ?? {}).replaceAll("'", "''"),
    status_sql: String($json.status ?? 'idea_approved').replaceAll("'", "''")
  }
}];
